const { JSDOM } = require('/app/node_modules/jsdom')

const fs = require('fs')
const bundle = fs.readFileSync('/tmp/opencode/combobox-bundle.js', 'utf-8')

const dom = new JSDOM(`<!DOCTYPE html><html><body></body></html>`, {
    runScripts: 'outside-only',
    url: 'http://localhost/',
    pretendToBeVisual: true,
})

let errors = []
let window = dom.window
let document = window.document

window.addEventListener('error', (e) => {
    errors.push(e.message)
})

if (! window.queueMicrotask) window.queueMicrotask = queueMicrotask

window.eval(bundle)

function boot(markup) {
    window.document.body.innerHTML = markup
    return new Promise(resolve => setTimeout(resolve, 150))
}

async function flush() {
    return new Promise(resolve => setTimeout(resolve, 50))
}

let failures = []

function check(desc, cond) {
    console.log((cond ? 'PASS' : 'FAIL') + ' - ' + desc)
    if (!cond) failures.push(desc)
}

;(async () => {
    const base = (selectedInit) => `
        <div x-data="{
            selected: ${selectedInit},
            people: [
                { id: 1, name: 'Wade Cooper' },
                { id: 2, name: 'Arlene Mccoy' },
                { id: 3, name: 'Devon Webb' },
            ]
        }">
            <div x-combobox x-model="selected">
                <input x-combobox:input :display-value="() => (person) => person.name" />
                <ul x-combobox:options>
                    <template x-for="person in people" :key="person.id">
                        <li x-combobox:option="person">
                            <span x-text="person.name"></span>
                        </li>
                    </template>
                </ul>
                <button x-combobox:button>Select Person</button>
            </div>
        </div>
    `

    // Scenario 1: Preselected value shows on load
    await boot(base(`{ id: 1, name: 'Wade Cooper' }`))
    let input = document.querySelector('input')
    check('preselected value displays on load', input.value === 'Wade Cooper')

    // Scenario 2: Open + select flow updates input
    await boot(base('null'))
    input = document.querySelector('input')
    check('empty input on load with no selection', input.value === '')

    let ul = document.querySelector('ul')
    check('options hidden initially', getComputedStyle(ul).display === 'none' || ul.hidden || !ul.offsetParent)

    document.querySelector('button').click()
