        walker(el, (el, skip) => {
            // If the element has already been initialized, don't do it again.
            // This prevents double initialization when the mutation observer
            // registers the same element more than once (e.g. when an element
            // is added, removed, then added again).
            if (el._x_isInit) return

            intercept(el, skip)

            initInterceptors.forEach(i => i(el, skip))

            directives(el, el.attributes).forEach(handle => handle())

            if (el._x_ignore) {
                skip()
            } else {
                el._x_isInit = true
            }
        })
    })
}

export function destroyTree(root) {
    walk(root, el => {
        cleanupAttributes(el)

        // Allow the element to be initialized fresh if it is re-added later.
        delete el._x_isInit
    })
}

// A node can be added, removed, and added again in a single batch of
    // mutations, causing it to appear in both lists identically. Sets give us
    // O(1) membership checks and let us iterate each unique node only once.
    let addedNodesSet = new Set(addedNodes)
    let removedNodesSet = new Set(removedNodes)

    for (let node of removedNodesSet) {
        // If an element gets moved on a page, it's registered
        // as both an "add" and "remove", so we want to skip those.
        if (addedNodesSet.has(node)) continue

        onElRemoveds.forEach(i => i(node))

        if (node._x_cleanups) {
            while (node._x_cleanups.length) node._x_cleanups.pop()()
        }
    }

    // Mutations are bundled together by the browser but sometimes
    // for complex cases, there may be javascript code adding a wrapper
    // and then an alpine component as a child of that wrapper in the same
    // function and the mutation observer will receive 2 different mutations.
    // when it comes time to run them, the dom contains both changes so the child
    // element would be processed twice as Alpine calls initTree on
    // both mutations. We mark all nodes as _x_ignored and only remove the flag
    // when processing the node to avoid those duplicates.
    addedNodesSet.forEach((node) => {
        node._x_ignoreSelf = true
        node._x_ignore = true
    })
    for (let node of addedNodesSet) {
        // If the node was eventually removed as part of one of his
        // parent mutations, skip it
        if (! node.isConnected) continue

        delete node._x_ignoreSelf
        delete node._x_ignore
        onElAddeds.forEach(i => i(node))
    }
    addedNodesSet.forEach((node) => {
        delete node._x_ignoreSelf
        delete node._x_ignore
    })

    addedNodes = null
    removedNodes = null
    addedNodesSet = null
    removedNodesSet = null
    addedAttributes = null
    removedAttributes = null
}

