const { JSDOM } = require('jsdom')

let failures = 0

function assert(cond, msg) {
    if (cond) {
        console.log('  PASS:', msg)
    } else {
        failures++
        console.log('  FAIL:', msg)
    }
}

async function run() {
    const dom = new JSDOM('<!DOCTYPE html><html><body></body></html>', {
        url: 'http://localhost',
        runScripts: 'dangerously',
        resources: 'usable',
        pretendToBeVisual: true,
    })

    const window = dom.window
    const document = window.document

    // Load freshly rebuilt Alpine bundle into the window.
    await new Promise((resolve, reject) => {
        const script = window.document.createElement('script')
        script.src = 'file:///app/packages/alpinejs/dist/cdn.js'
        script.onload = resolve
        script.onerror = reject
        window.document.head.appendChild(script)
    })

    const Alpine = window.Alpine
    await Alpine.start()
    await window.__nextTick ? window.__nextTick() : Promise.resolve()
    // Allow microtasks/mutation flush.
    await new Promise(r => window.setTimeout(r, 20))

    // ---------- Test 1: add, remove, then add again within a short window ----------
    {
        const el = document.createElement('div')
        el.innerHTML = '<h1 x-text="msg"></h1>'
        el.setAttribute('x-data', '{ msg: \'hello\' }')
        const container = document.createElement('div')
        document.body.appendChild(container)

        // add
        container.appendChild(el)
        // remove
        container.removeChild(el)
        // re-add synchronously (same mutation batch in real observer, or queued)
        container.appendChild(el)

        await new Promise(r => window.setTimeout(r, 20))

        const h1 = el.querySelector('h1')
        assert(h1.textContent === 'hello', 'Test1: element added/removed/re-added initializes (x-text renders)')
    }

    // ---------- Test 2: x-data init counter runs exactly once on add/remove/add ----------
    {
        window.__count = 0
        const el = document.createElement('div')
        el.setAttribute('x-data', '{ n: 0 }')
        el.setAttribute('x-init', 'window.__count++')
        const container = document.createElement('div')
        document.body.appendChild(container)

        container.appendChild(el)
        container.removeChild(el)
        container.appendChild(el)

        await new Promise(r => window.setTimeout(r, 20))

        assert(window.__count === 1, `Test2: x-init ran exactly once (got ${window.__count})`)
    }

    // ---------- Test 3: wrapper + child both added in same batch ----------
    {
        const wrapper = document.createElement('div')
        const child = document.createElement('span')
        child.setAttribute('x-text', '"wrapped"')
        wrapper.appendChild(child)

        const container = document.createElement('div')
        document.body.appendChild(container)
        container.appendChild(wrapper)

        // Now add a fresh child to the *already added* wrapper and to container
        // in one "batch" (two separate appended mutations).
        const child2 = document.createElement('span')
        child2.setAttribute('x-text', '"second"')
        for (const n of [wrapper, child2]) n
        wrapper.appendChild(child2)

        await new Promise(r => window.setTimeout(r, 20))

        assert(wrapper.querySelector('span').textContent === 'wrapped', 'Test3: pre-added child inside wrapper initialized')
        assert(child2.textContent === 'second', 'Test3: child added in later batch initialized')
    }

    // ---------- Test 4: destroy cleans _x_isInit so re-add re-initializes ----------
    {
        window.__count2 = 0
        const el = document.createElement('div')
        el.setAttribute('x-data', '{}')
        el.setAttribute('x-init', 'window.__count2++')
        const container = document.createElement('div')
        document.body.appendChild(container)

        container.appendChild(el)
        await new Promise(r => window.setTimeout(r, 20))
        assert(window.__count2 === 1, 'Test4: init ran once before removal')

        container.removeChild(el)
        await new Promise(r => window.setTimeout(r, 20))

        container.appendChild(el)
        await new Promise(r => window.setTimeout(r, 20))

        assert(window.__count2 === 2, `Test4: re-added after a real removal re-initializes (got ${window.__count2})`)
    }

    // ---------- Test 5: x-ignore still skips children ----------
    {
        const el = document.createElement('div')
        el.setAttribute('x-data', '{ foo: \'bar\' }')
        el.innerHTML = '<div x-ignore><span x-text="foo"></span></div>'
        document.body.appendChild(el)

        await new Promise(r => window.setTimeout(r, 20))

        const span = el.querySelector('span')
        assert(span.textContent === '', 'Test5: x-ignore prevents child initialization')
        // And x-ignore.self should still initialize children
    }

    // ---------- Test 6: x-ignore.self initializes children ----------
    {
        const el = document.createElement('div')
        el.setAttribute('x-data', '{ foo: \'bar\' }')
        el.innerHTML = '<h1 x-ignore.self :class="foo"><span x-text="foo"></span></h1>'
        document.body.appendChild(el)

        await new Promise(r => window.setTimeout(r, 20))

        const span = el.querySelector('span')
        const h1 = el.querySelector('h1')
        assert(span.textContent === 'bar', 'Test6: x-ignore.self still initializes children')
        assert(h1.className === '', 'Test6: x-ignore.self prevents own directives')
    }

    // ---------- Test 7: x-if toggle (add/remove via mutation observer) ----------
    {
        const el = document.createElement('div')
        el.setAttribute('x-data', '{ show: true }')
        el.innerHTML = '<button @click="show = !show">toggle</button><template x-if="show"><span x-text="\'shown\'"></span></template>'
        document.body.appendChild(el)

        await new Promise(r => window.setTimeout(r, 30))
        const button = el.querySelector('button')
        assert(el.querySelector('span') && el.querySelector('span').textContent === 'shown', 'Test7a: x-if content shown')

        button.click()
        await new Promise(r => window.setTimeout(r, 30))
        assert(!el.querySelector('span'), 'Test7b: x-if content hidden')

        button.click()
        await new Promise(r => window.setTimeout(r, 30))
        const span = el.querySelector('span')
        assert(span && span.textContent === 'shown', 'Test7c: x-if content shown again after re-toggle')
    }

    // ---------- Test 8: x-for renders and updates ----------
    {
        const el = document.createElement('div')
        el.setAttribute('x-data', '{ items: [\'a\', \'b\', \'c\'] }')
        el.innerHTML = '<template x-for="item in items" :key="item"><div x-text="item"></div></template>'
        document.body.appendChild(el)

        await new Promise(r => window.setTimeout(r, 30))

        const items = [...el.querySelectorAll('div')].map(d => d.textContent)
        assert(JSON.stringify(items) === JSON.stringify(['a', 'b', 'c']), `Test8: x-for renders (got ${JSON.stringify(items)})`)
    }

    // ---------- Test 9: x-text effect updates on state change ----------
    {
        const el = document.createElement('div')
        el.setAttribute('x-data', '{ foo: \'one\' }')
        el.innerHTML = '<span x-text="foo"></span>'
        document.body.appendChild(el)

        await new Promise(r => window.setTimeout(r, 20))
        assert(el.querySelector('span').textContent === 'one', 'Test9a: x-text initial value')

        el.__x = el
        // Change state via Alpine
        Alpine.effect = Alpine.effect // noop reference guard
        // Access reactive data through $data
        const dataEl = el
        const spinner = document.createElement('i')
        document.body.appendChild(spinner)
        const $data = Alpine.$data(dataEl)
        $data.foo = 'two'
        await new Promise(r => window.setTimeout(r, 20))
        assert(el.querySelector('span').textContent === 'two', `Test9b: x-text updates (got ${el.querySelector('span').textContent})`)
    }

    // ---------- Test 10: x-show toggle ----------
    {
        const el = document.createElement('div')
        el.setAttribute('x-data', '{ open: false }')
        el.innerHTML = '<button @click="open = !open">t</button><div x-show="open" id="panel">panel</div>'
        document.body.appendChild(el)

        await new Promise(r => window.setTimeout(r, 20))
        const panel = el.querySelector('#panel')
        assert(getComputedStyle(panel).display === 'none', 'Test10a: x-show initial hidden')

        el.querySelector('button').click()
        await new Promise(r => window.setTimeout(r, 20))
        assert(getComputedStyle(panel).display !== 'none', 'Test10b: x-show toggled visible')
    }

    // ---------- Test 11: x-html with nested alpine ----------
    {
        const el = document.createElement('div')
        el.setAttribute('x-data', "{ bar: 'baz', foo: '<h1 x-text=&quot;bar&quot;></h1>' }")
        el.setAttribute('x-html', 'foo')
        document.body.appendChild(el)

        await new Promise(r => window.setTimeout(r, 40))
        const h1 = el.querySelector('h1')
        assert(h1 && h1.textContent === 'baz', `Test11: x-html initializes nested alpine content (got ${h1 && h1.textContent})`)

        // update x-html content
        const $data = Alpine.$data(el)
        $data.foo = '<h1 x-text=&quot;bar&quot;></h1><p x-text=&quot;bar&quot;></p>'
        await new Promise(r => window.setTimeout(r, 40))
        const p = el.querySelector('p')
        assert(p && p.textContent === 'baz', `Test12 (x-html): new content after update initialized (got ${p && p.textContent})`)
    }

    console.log('\n===', failures === 0 ? 'ALL PASS' : `${failures} FAILURES`, '===')
    process.exit(failures === 0 ? 0 : 1)
}

run().catch(e => {
    console.error('HARNESS ERROR:', e)
    process.exit(1)
})

