arguments.newString:
test('no side effects when directives are added to an element that is removed afterwards',
    html`
        <div x-data="{
            foo: 0,
            mutate() {
                let span = document.createElement('span')
                span.setAttribute('x-on:keydown.a.window', 'foo = foo+1')
                let container = document.getElementById('container')
                container.appendChild(span)
                container.remove()
            }
        }">
            <button @click="mutate()">Mutate</button>
            <p id="container"></p>
            <input type="text">

            <span x-text="foo"></span>
        </div>
    `,
    ({ get }) => {
        get('span').should(haveText('0'))
        get('button').click()
        get('input').type('a')
        get('span').should(haveText('0'))
    }
)

test('initialises an element that is added, removed, and added again in the same batch',
    html`
        <div x-data="{
            test() {
                let el = document.createElement('div')
                el.setAttribute('x-data', '{ msg: \'hello\' }')
                el.innerHTML = '<h1 x-text="msg"></h1>'
                this.$root.appendChild(el)
                el.remove()
                this.$root.appendChild(el)
            }
        }">
            <button @click="test()">Test</button>
        </div>
    `,
    ({ get }) => {
        get('button').click()
        get('h1').should(haveText('hello'))
    }
)

test('only initialises an element once when it is added, removed, and added again in the same batch',
    html`
        <div x-data="{
            foo: 0,
            bar: 0,
            test() {
                let el = document.createElement('div')
                el.setAttribute('x-data', '{ init() { this.bar++ } }')
                el.setAttribute('x-init', 'foo++')
                this.$root.appendChild(el)
                el.remove()
                this.$root.appendChild(el)
            }
        }">
            <span id="one" x-text="foo"></span>
            <span id="two" x-text="bar"></span>
            <button @click="test()">Test</button>
        </div>
    `,
    ({ get }) => {
        get('span#one').should(haveText('0'))
        get('span#two').should(haveText('0'))
        get('button').click()
        get('span#one').should(haveText('1'))
        get('span#two').should(haveText('1'))
    }
)

