import { closestDataStack, mergeProxies } from 'alpinejs/src/scope'
import { injectMagics } from 'alpinejs/src/magics'
import { generateEvaluatorFromFunction, runIfTypeOfFunction } from 'alpinejs/src/evaluator'
import { tryCatch } from 'alpinejs/src/utils/error'

export function cspEvaluator(el, expression) {
  let dataStack = generateDataStack(el)

  if (typeof expression === 'function') {
    return generateEvaluatorFromFunction(dataStack, expression)
  }

  return generateEvaluator(el, expression, dataStack)
}

function generateDataStack(el) {
  let overriddenMagics = {}

  injectMagics(overriddenMagics, el)

  return [overriddenMagics, ...closestDataStack(el)]
}

function generateEvaluator(el, expression, dataStack) {
  let evaluator = (receiver = () => {}, { scope = {}, params = [] } = {}) => {
    let completeScope = mergeProxies([scope, ...dataStack])

    if (completeScope[expression] === undefined) {
      console.warn(`Alpine Expression Error: "${expression}" was not found in the scope.` +
        ` The CSP build of Alpine can only access properties and methods that are explicitly` +
        ` registered on the component. Read the docs for more information:` +
        ` https://alpinejs.dev/advanced/csp`)
    }

    runIfTypeOfFunction(receiver, completeScope[expression], completeScope, params)
  }

  return tryCatch.bind(null, el, expression, evaluator)
}

import Alpine from 'alpinejs/src/alpine'

// The CSP build of Alpine is an alternate version of Alpine that can run in
// environments with a Content-Security-Policy that forbids the use of
// "unsafe-eval". The standard build of Alpine evaluates JavaScript by
// creating functions at runtime from string expressions, which violates this
// policy.
//
// Instead, this build swaps in a custom evaluator (see ./evaluator) that
// restricts expressions to simple property lookups and method calls on your
// component's scope. This means you must register your component data via
// Alpine.data() and cannot write inline JavaScript expressions like
// "count++".
import { cspEvaluator } from './evaluator'

Alpine.setEvaluator(cspEvaluator)

import { reactive, effect, stop, toRaw } from '@vue/reactivity'

// Set up the reactivity engine that Alpine relies on for tracking and
// responding to changes in your data.
Alpine.setReactivityEngine({ reactive, effect, release: stop, raw: toRaw })

// Import the core magics ($el, $refs, $store, etc.) and directives
// (x-data, x-text, x-show, etc.) so they are available to this build.
import 'alpinejs/src/magics/index'
import 'alpinejs/src/directives/index'

export default Alpine

