const fs = require('fs')
const { JSDOM } = require('/app/node_modules/jsdom')

const arg = process.argv[2]
const dist = arg === 'pristine' ? '/tmp/opencode/pristine-ui-cdn.js' : '/app/packages/ui/dist/cdn.js'
const uiCdn = fs.readFileSync(dist, 'utf8')
const alpineCdn = fs.readFileSync('/app/packages/alpinejs/dist/cdn.js', 'utf8')

const html = `<div
    x-data="{ active: null, people: [
        { id: 1, name: 'Wade Cooper' },
        { id: 2, name: 'Arlene Mccoy' },
        { id: 3, name: 'Devon Webb' },
        { id: 4, name: 'Tom Cook' },
        { id: 5, name: 'Tanya Fox', disabled: true },
        { id: 6, name: 'Hellen Schmidt' },
        { id: 7, name: 'Caroline Schultz' },
        { id: 8, name: 'Mason Heaney' },
        { id: 9, name: 'Claudie Smitham' },
        { id: 10, name: 'Emil Schaefer' },
    ]}"
    x-listbox
    x-model="active"
    by="id"
>
    <label x-listbox:label>Assigned to</label>
    <button x-listbox:button x-text="active ? active.name : 'Select Person'"></button>
    <ul x-listbox:options>
        <template x-for="person in people" :key="person.id">
            <li :option="person.id" x-listbox:option :value="person" :disabled="person.disabled">
                <span x-text="person.name"></span>
            </li>
        </template>
    </ul>
</div>`

const dom = new JSDOM(`<!DOCTYPE html><html><body><div id="root">${html}</div></body></html>`, { runScripts: 'outside-only', pretendToBeVisual: true, url: 'http://localhost/' })
const { window } = dom
window.requestAnimationFrame = cb => setTimeout(() => cb(Date.now()), 0)
let errs = []
window.addEventListener('error', e => { errs.push((e.error && e.error.message) || e.message) })
window.eval(alpineCdn); window.eval(uiCdn)
window.Alpine.start()
setTimeout(() => {
  const btn = window.document.querySelector('button')
  const before = btn.textContent.trim()
  let clickErr = null
  try {
    const opt2 = window.document.querySelector('[option="2"]')
    if (opt2) opt2.dispatchEvent(new window.MouseEvent('click', { bubbles: true }))
  } catch (e) { clickErr = e.message }
  setTimeout(() => {
    const after = window.document.querySelector('button').textContent.trim()
    console.log(JSON.stringify({ build: arg, before, after, clickErr, errs }))
    process.exit(0)
  }, 100)
}, 300)
EOF
